def identity(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def historical_universe(root, read_json):
    spec = read_json(root / REQUIREMENTS)
    applicable = {}
    for requirement in spec['requirements']:
        profiles = spec['profile_sets'][requirement['profile_set']]
        if 'transfer' in profiles:
            name = requirement['id']
            if name in applicable:
                raise ValueError('duplicate historical requirement: ' + name)
            applicable[name] = {**requirement, 'statement': spec['statements'][name]}
    occurrences = {}
    for name, requirement in applicable.items():
        selector = {'source': REQUIREMENTS, 'kind': 'requirement', 'id': name,
                    'profile_set': requirement['profile_set']}
        occurrences[identity(selector)] = selector
    # Preserve source occurrences even when their old path was another family:
    # this is shared-contract applicability, not a claim that those tests cover Transfer.
    for fingerprint in spec['test_source_fingerprints']:
        selector = {'source': REQUIREMENTS, 'kind': 'historical-test-source', **fingerprint}
        occurrences[identity(selector)] = selector
    for fingerprint in spec['lean_declaration_fingerprints']:
        if '/Transfer/' in fingerprint['path']:
            selector = {'source': REQUIREMENTS, 'kind': 'historical-lean-declaration', **fingerprint}
            occurrences[identity(selector)] = selector
    for row in csv.DictReader(io.StringIO((root / MIGRATION).read_text(encoding='utf-8-sig')), delimiter='\t'):
        # Every retained member is accounted, including native and protocol members.
        # Applicability must be explicitly reviewed; no keyword classifier retires it.
        selector = {**{k: row[k] for k in ('source', 'member', 'name', 'owner', 'member_sha256')},
                    'historical_kind': row['kind'], 'kind': 'migration-member'}
        selector['inventory'] = MIGRATION
        key = identity(selector)
        if key in occurrences:
            raise ValueError('duplicate historical migration selector: ' + key)
        occurrences[key] = selector
    external = {}
    for line_number, line in enumerate((root / EXTERNAL).read_text(encoding='utf-8').splitlines(), 1):
        match = re.match(r'^\| `([^`]+)` \| (.*?) \| (.*?) \| (.*?) \| (.*?) \|$', line)
        if match:
            name, contract, rust, go, old_status = match.groups()
            selector = {'source': EXTERNAL, 'kind': 'external-check', 'line': line_number,
                        'id': name, 'contract': contract, 'rust': rust, 'go': go,
                        'historical_status': old_status}
            external[name] = selector
            occurrences[identity(selector)] = selector
    return applicable, external, occurrences



